294	/* Purges samples older than window size from buffer */
295	static void
296	purge_old(window_t *w, time_t now, unsigned int window_sec)
297	{
298	    if (!w || w->count == 0) return;
299	
300	    size_t idx = w->head;
301	    for (size_t i = 0; i < w->count; ++i) {
302	        if (difftime(now, w->ts[idx]) > window_sec) {
303	            /* Drop this sample: shift tail forward */
304	            w->count--;
305	        } else {
306	            break; /* because items are added in chronological order */
307	        }
308	        if (idx == 0) idx = MAX_WINDOW_SIZE - 1;
309	        else          idx--;
310	    }
311	}
