315	add_sample(window_t *w, double val, time_t ts)
316	{
317	    if (!w) return;
318	    if (w->count < MAX_WINDOW_SIZE) {
319	        w->count++;
320	    }
321	    /* move head */
322	    w->head = (w->head + 1) % MAX_WINDOW_SIZE;
323	    w->samples[w->head] = val;
324	    w->ts[w->head]      = ts;
325	}
