327	static double
328	compute_avg(const window_t *w)
329	{
330	    if (!w || w->count == 0) return NAN;
331	    double sum = 0;
332	    size_t idx = w->head;
333	    for (size_t i = 0; i < w->count; ++i) {
334	        sum += w->samples[idx];
335	        if (idx == 0) idx = MAX_WINDOW_SIZE - 1;
336	        else          idx--;
337	    }
338	    return sum / (double)w->count;
339	}
